INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65789025', 65789025, 'analyze_legacy', 'Kota Tangerang Selatan', 'kabkota', 'DINAS KESEHATAN', 'Belanja Jasa Pengolahan Sampah UPTD Puskesmas Rawa Mekar Jaya', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 2400000, 'February 2026', 'BLUD', 0, 1, '1 tahun', 'Jasa pengangkutan dan pengolahan limbah medis', '- Memiliki Izin Pengangkutan Limbah B3 dari Kementerian Lingkungan Hidup dan Kehutanan (KLHK) yang masih berlaku. - Memiliki Izin Penyelenggaraan Angkutan Barang Khusus/B3 dari Dirjen Perhubungan Darat. - Mampu melampirkan Dokumen Kontrak Kerja sama dan Surat Kerjasama dengan pihak ketiga (jika pengolahan disubkontrakkan). - Memiliki akun Simpel (Sistem Pelaporan Limbah). - Memiliki NIB dengan KBLI 38120 (Pengumpulan Limbah Berbahaya) atau KBLI 38220 (Treatment dan Pembuangan Limbah Berbahaya). - Memiliki sarana insinerator berizin atau kerjasama pemusnahan metode insinerator (≥800°C) atau autoclave sesuai ketentuan yang berlaku. - Penyedia wajib melaksanakan jasa pengangkutan dan pengelolaan limbah medis B3 (limbah infeksius, benda tajam/safety box, limbah farmasi kadaluarsa, dan limbah medis padat lainnya) dengan pengambilan minimal 1–2 kali per bulan, - menggunakan kendaraan khusus limbah B3 berizin dan berlabel simbol bahaya, serta diolah di fasilitas berizin dengan persyaratan: 1. Menggunakan kendaraan tertutup (box) yang didesain khusus untuk limbah B3, dilengkapi penanda/simbol bahaya B3. 2. Kendaraan memiliki alat penahan sampah/kontainer, mudah dibersihkan, dan kedap air. 3. Memiliki nomor telepon perusahaan yang tercantum secara permanen pada alat angkut. 4. Tahun pembuatan kendaraan umumnya dibatasi (misalnya di atas tahun 2019) untuk menjamin kelayakan teknis. - Prosedur wajib meliputi penimbangan, pencatatan, dan penandatanganan manifest oleh kedua belah pihak (rumah sakit/puskesmas dan transporter)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2363047);
