INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65793976', 65793976, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli Backend Development Coordinator Rancangan Pengembangan Sistem Informasi Evaluasi Pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 55275000, 'August 2026', 'APBD', 1, 1, '1 orang x 3 bulan', 'Merancang dan mengelola struktur backend untuk memastikan efisiensi, skalabilitas dan keamanan sistem Memastikan bahwa semua pengembangan backend mematuhi standar coding, praktik terbaik, dan kebijakan keamanan Memimpin dan mengoordinasikan pekerjaan tim backend, termasuk memberikan arahan teknis dan mendistribusikan tugas Mendukung siklus pengembangan (konsep, desain, pengujian, rilis, operasional) Merancang struktur database yang optimal untuk penyimpanan dan pengambilan data Melakukan pemeliharaan database, termasuk pencadangan (backup), pengoptimalan, dan migrasi data Memastikan keamanan data melalui enkripsi dan teknik keamanan lainnya Memastikan API dapat menangani permintaan skala besar dengan efisien Mengatasi berbagai bugs dan errors yang terjadi pada aplikasi dari sisi backend Berupaya untuk terus berinovasi dalam hal meningkatkan kualitas dan performa dari sistem aplikasi Memantau performa aplikasi backend secara berkala untuk memastikan stabilitas Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki Membuat script pemrograman yang terstruktur sehingga mempermudah dan dimengerti oleh progammer lain jika ke depannya akan dikembangkan Berkoordinasi dengan front-end developer untuk memastikan integrasi apliasi berjalan lancar', 'Pendidikan terakhir S1 jurusan Ilmu Komputer/Sistem Informasi/Teknik Informatika Memiliki pengalaman kerja sebagai programmer minimal 8 sampai dengan 12 tahun Memiliki kemampuan bahasa pemograman Java, Swagger, Angular (Mengerti Java Spring Boot lebih diutamakan) Memiliki konsep OOP dan/atau functional programming Memiliki kemampuan bahasa pemograman NodeJS dan PHP, Golang, Bootstrap menjadi nilai tambah Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres Lebih diutamakan)Memahami konsep Container, REST API, Git Continous Integration dan Deployment menjadi nilai tambah Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres Lebih diutamakan) Memahami konsep Container, REST API, Git Continous Integration dan Deployment menjadi nilai tambah Diutamakan pernah mengikuti pelatihan ISO 27001', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2364374);
