INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65834352', 65834352, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Individu Kebijakan Pangan dan Gizi, Kegiatan Penyusunan Rekomendasi Kebijakan Pembangunan Sosial dan Penanggulangan Kemiskinan Tahun 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99660000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Dalam rangka mendukung pelaksanaan kegiatan Penyusunan Kajian Kebijakan Pangan dan Gizi untuk Mendukung Pelaksanaan Kegiatan Penyusunan Rekomendasi Kebijakan Pembangunan Sosial dan Penanggulangan Kemiskinan.', '1. Melakukan identifikasi permasalahan, tantangan, dan isu strategis di bidang sosial, serta menyusun alternatif rekomendasi kebijakan berdasarkan hasil analisis dan kajian. 2. Mendukung Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan dalam penyusunan dokumen kajian dan rekomendasi kebijakan melalui penguatan aspek penulisan, penyuntingan, dan penyajian substansi kebijakan secara sistematis dan berbasis bukti. 3. Melakukan penyuntingan substantif (substantive editing) dan penyuntingan bahasa (copy editing) terhadap dokumen kajian kebijakan untuk memastikan kejelasan argumentasi, konsistensi logika kebijakan, serta kesesuaian dengan kaidah penulisan kebijakan pemerintah. 4. Menyajikan hasil kajian dan rekomendasi kebijakan dalam bentuk tata letak (layout) dan desain dokumen yang informatif, profesional, dan mudah dipahami oleh pengambil kebijakan, termasuk penyusunan grafik, tabel, dan infografis kebijakan. 5. Menyusun bahan pendukung kebijakan berupa bahan paparan (presentasi), ringkasan eksekutif, dan materi visual kebijakan untuk digunakan dalam rapat pimpinan, forum lintas kementerian/lembaga, advokasi, maupun pertemuan strategis lainnya. 6. Menyusun laporan pelaksanaan kegiatan penyusunan dan penulisan kajian kebijakan secara berkala sebagai bagian dari pertanggungjawaban kinerja dan administrasi kegiatan. 7. Melakukan transfer of knowledge atas hasil pekerjaan kepada tim sekretariat Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan Kementerian PPN/Bappenas untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal 8. Melaksanakan tugas lain yang relevan sesuai arahan Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan dalam mendukung penyusunan dan penyampaian rekomendasi kebijakan pembangunan sosial dan penanggulangan kemiskinan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2366295);
