INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65837980', 65837980, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'SEKRETARIAT JENDERAL', 'Pengadaan Tenaga Ahli Bidang Pembangunan Ekonomi dan Pemberdayaan Masyarakat', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 80000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Tenaga Ahli Bidang Pembangunan Ekonomi dan Pemberdayaan Masyarakat pada Biro Administrasi Pimpiman Sekretariat Jenderal Kementerian Dalam Negeri adalah sebagai berikut: 1. Melakukan inventarisasi data dan informasi terkait dengan Ekonomi Pembangunan dan Pemberdayaan Masyarakat dari berbagai media informasi ke dalam media penyimpanan tertentu sehingga data tersebut dapat digunakan secara efisien dan berkelanjutan; 2. Melakukan pengolahan dan penyajian data dan informasi dalam bentuk infografis; 3. Memberikan saran dan masukan kepada Bapak Wakil Menteri terkait dengan kebijakan di bidang Ekonomi Pembangunan dan Pemberdayaan Masyarakat; 4. Melaksanakan tugas lain yang diberikan atau di perintahkan pimpinan pada Biro Administrasi Pimpinan Kemendagri; 5. Melakukan penyusunan laporan pelaksanaan tugas secara berkala kepada Pimpinan pada Biro Administrasi Pimpinan Kemendagri.', 'Kualifikasi kebutuhan personil Tenaga Ahli Bidang Pembangunan Ekonomi dan Pemberdayaan Masyarakat pada Biro Administrasi Pimpinan Sekretariat Jenderal Kementerian Dalam Negeri adalah sebagai berikut: 1. Sarjana S1 atau S2 semua jurusan 2. Memiliki NPWP dan Kartu Tanda Penduduk (KTP). 3. Memiliki CV / Daftar Riwayat Hidup. 4. Memiliki Tanggapan Terhadap Kerangka Acuan Kerja (KAK). 5. Melampirkan tahapan Pelaksanaan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2368989);
